 if(draft.score===''||draft.score===null||draft.score===undefined||!Number.isFinite(Number(draft.score))||Number(draft.score)<0||Number(draft.score)>10)throw Error('Indica el RPE comunicado por la jugadora, entre 0 y 10.');
