 const data={player_id:draft.player_id,score:Number(draft.score),duration_minutes:minutes};
 if(draft.event_id)return {...data,event_id:draft.event_id};
 const context=String(draft.context||'').trim();if(!context||context.length>160)throw Error('Indica el equipo, categoría o actividad.');
